    f->g = (g * 4096) / (4096 + g);
    f->g2 = va_q12(f->g, f->g);
    f->g3 = va_q12(f->g2, f->g);
    f->k = clamp(res, 0, 32767) * 28672 / 32767; /* 7.0: below the 3-pole oscillation threshold 8 */
