    case 1: return sine_i((uint32_t)(x + ((uint32_t)(((int32_t)(sine_i((uint32_t)(x * 3u) << 19)) * (int32_t)((int32_t)((t >> 10) & 15u) * 3)) >> 6))) << 19); /* FM, its index walking */
    case 2: return sine_i((uint32_t)((x >> 4) * R[(0x36364689u >> ((st & 7u) * 4u)) & 7u]) << 19) * E >> 15; /* a melody, a nibble table */
    case 3: return sine_i((uint32_t)(x * (1u + ((t >> 12) & 3u))) << 19) * sine_i((uint32_t)(x * (((t >> 9) & 7u) + 1u)) << 19) >> 15; /* a ring, rhythmic */
