    case 11: return sine_i((uint32_t)(x + ((uint32_t)(((int32_t)(sine_i((uint32_t)(t << 2) << 19)) * (int32_t)(6)) >> 6))) << 19); /* a vibrato, deep (4 Hz) */
    case 12: return sine_i((uint32_t)((uint32_t)(sine_i((uint32_t)(x) << 19) * (2 + (int32_t)((t >> 11) & 7u))) >> 2) << 19); /* folded, rhythmic */
    case 13: a = sine_i((uint32_t)(x * (1u + (st & 1u))) << 19); b = sine_i((uint32_t)((x >> 4) * (24u + (st & 6u) * 4u)) << 19); /* rectified, leaping */
             return (a < 0 ? -a : a) - (b < 0 ? -b : b);
    case 14: return sine_i((uint32_t)(x & ~((1u << (4u + (st & 7u))) - 1u)) << 19); /* a staircase sine */
    case 15: return sine_i((uint32_t)(x * (((t >> 8) % 7u) + 1u)) << 19) * E >> 15; /* partials mod 7 */
