    drift += (((int32_t)(noise32(&nst) >> 22) - 512) - drift) >> 3;
    cut = clamp((p[P_E5] << 8) + m->cutoff + drift, 0, 127 << 8);
    tsvf_coef_k(&flt, cut, k);
