    static const param_desc_t fm = {"FM ENV", F_PCT, 0, 127, 0, 0, 0};
    static const param_desc_t fold = {"FOLD", F_PCT, 0, 127, 0, 0, 0};
    static const char *const kick_names[] = {"PUNCH", "ROUND"};
