    static const char *const fields[] = {"PIT", "PMD", "DCY", "NOI", "COL", "PIT", "PMD", "DCY", "NOI", "COL", "MOD", "PMT", "DRV", "LAY", "FB", "SND"};
    if (id < 264u) { str_cpy(b, dx_desc(id)->label, 9); return; }
    uint32_t n = id - 264u, f = n % 16u;
