        int32_t gl = 4096 - (pan > 0 ? pan * 64 : 0), gr = 4096 + (pan < 0 ? pan * 64 : 0), sp = t->p[P_SPRD];
        glm = gl; grm = gr; gld = (gl * sp) >> 8; grd = -((gr * sp) >> 8);
