    ((t)->spread_on) = !dx_track(t) && t->p[P_SPRD] > 0 && (trk_vmode(t) == V_POLY || trk_vmode(t) == V_UNISON)
                  ? (ens ? 2u : 1u) : 0u; /* (SPREAD, mix_spread: 1 the voices' alternation; 2 the ENSEMBLE's own stereo, eng_ensemble.c) */
