/* MIDI IN on the TRS jack: PH8 -> input channel 1 -> UART1 RX, 31250 baud,
 * RX DMA into a 128-byte ring, polled from the TIMER5 ISR (no UART IRQ).
 * FELUCCA_UART=0 disables this input. Channel
 * messages go into midi_in_q next to USB, as
 * USB-MIDI packets (cable 0, CIN = status >> 4), so seq.c routes them by channel
 * exactly as USB (CH1-4 or SEL;
 * host tests: midi_uart_test, hostsim TRACKS trs_test);
 * Clock/Start/Continue/Stop retain timestamps and source; other realtime,
 * system common and SysEx are ignored (no SysEx->UBOOT from DIN). */
/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* FM-1 UART1 as MIDI IN: PH8 -> input
 * channel 1 -> UART1 RX, 31250 baud, RX DMA into a ring, polled (no IRQ).
 * The MIDI parser is midi_uart.c. RX verified on hardware.
 *
 *   fm1_uart1_midi_init(ring, len)   len a power of two, ring aligned 16;
 *                                    before TIMER5 starts (PORTH RMW)
 *   fm1_uart1_rx_take()              bytes DMA'd since the last call
 */
       
static inline void fm1_uart1_midi_init(volatile uint8_t *ring, uint32_t len)
{
    (*(volatile uint32_t *)0x12100u) = 0x3400u; /* off, pendings cleared */
    (*(volatile uint32_t *)0x12104u) = 0;
    (*(volatile uint32_t *)0x10010u) = ((*(volatile uint32_t *)0x10010u) & ~(3u << 10)) | (1u << 10);
    (*(volatile uint32_t *)0x51028u) &= ~0x80u;
    (*(volatile uint32_t *)0x51028u) = ((*(volatile uint32_t *)0x51028u) & ~0x70u) | (5u << 4); /* UT1 RX = input ch 1 */
    (*(volatile uint32_t *)0x51024u) = ((*(volatile uint32_t *)0x51024u) & ~0x3F00u) | (49u << 8);/* ch 1 = PH8 */
    (*(volatile uint32_t *)0x501D4u) &= ~(1u << 8);
    (*(volatile uint32_t *)0x501CCu) |= 1u << 8;
    (*(volatile uint32_t *)0x501C8u) |= 1u << 8;
    (*(volatile uint32_t *)0x501D0u) |= 1u << 8;
    (*(volatile uint32_t *)0x1211Cu) = (uint32_t)(uintptr_t)ring;
    (*(volatile uint32_t *)0x12120u) = (uint32_t)(uintptr_t)ring + len;
    (*(volatile uint32_t *)0x12124u) = len;
    (*(volatile uint32_t *)0x12108u) = 48000000u / 31250u / 4u - 1u; /* 383 */
    (*(volatile uint32_t *)0x12110u) = 60000u;
    __asm__ volatile("csync" ::: "memory");
    (*(volatile uint32_t *)0x12100u) = 0x40u | 0x80u | 0x1000u | 0x400u; /* RXDMA, RDC, clear R/OT; no IEs */
    __asm__ volatile("csync" ::: "memory");
    (*(volatile uint32_t *)0x12100u) |= 1u; /* UTEN last */
}
/* CDC diagnostics (console.c): takes that came with a receive / overtime event pending (CON0 bits 14 / 11) and takes
 * that returned a count with none: HRXCNT outside an event is not documented as a fresh batch, a retained count would
 * replay old bytes as new ones (docs/sequencer/external-clock.md) */
