static void lat_put(uint32_t *a, uint32_t n, uint32_t on)
{
    a[n >> 5] = on ? a[n >> 5] | 1u << (n & 31u) : a[n >> 5] & ~(1u << (n & 31u));
}
static int lat_any(const uint32_t *a) { return (a[0] | a[1] | a[2] | a[3]) != 0u; }
/* the keys' and MIDI IN's holding of the ARP's chord: ARP HOLD, or any LATCH */
static int arp_hold(const track_t *t) { return t->p[P_AHOLD] || latch_mode(t) != LT_OFF; }
/* a press with no key down starts a new chord (HOLD, NEW); STACK adds to it */
static int arp_replace(const track_t *t)
{
    uint32_t m = latch_mode(t);
    return m == LT_NEW || (t->p[P_AHOLD] && m != LT_STACK);
}
static int midi_note_held(const track_t *t, uint32_t note);
static int midi_local_held(const track_t *t, uint32_t note);
/* Before a fresh input replaces chord_last, its released pitches become older owners. */
static void latch_bus_capture(track_t *t)
{
    uint32_t k = trk_index(t), j;
    if (t->p[P_CHRD] == CH_BUS && !t->p[P_AMODE] && latch_mode(t) != LT_OFF)
        for (j = 0; j < 4u; j++)
            PKV(179)[k][j] |= PKV(178)[k][j];
    PKV(180)[k] = 0;
}
/* A released BUS input remains an owner even when another held chord shares a pitch
 * (input_off is deliberately skipped for those shared pitches). Inspect the whole list
 * before input_off consumes STACK's lat_eat bits. Sustain reaches this on pedal-up. */
static void latch_bus_release(track_t *t, const uint8_t *notes, uint32_t n)
{
    uint32_t k = trk_index(t), j;
    int matches = n == PKV(175)[k].n;
    if (t->p[P_CHRD] != CH_BUS || t->p[P_AMODE] || latch_mode(t) == LT_OFF || !n)
        return;
    for (j = 0; j < n; j++) {
        if (lat_get(PKV(177)[k], notes[j])) return;
        if (j >= PKV(175)[k].n || notes[j] != PKV(175)[k].note[j]) matches = 0;
    }
    if (matches)
        PKV(180)[k] = 1;
    else
        for (j = 0; j < n; j++)
            lat_put(PKV(179)[k], notes[j], 1);
}
static void chord_live_sync(uint32_t i);
/* the latched notes end (LATCH off, ARP on, a new set, the release gesture; the notes a key holds are not among them) */
static void latch_free(track_t *t)
{
    uint32_t k = trk_index(t), n;
    for (n = 0; n < 128u; n++)
        if (lat_get(PKV(178)[k], n) || lat_get(PKV(179)[k], n)) {
            if (!midi_local_held(t, n) && !midi_note_held(t, n))
                trk_note_off(t, n);
            PKV(181)[k][n] = 0;
        }
    memset(PKV(179)[k], 0, sizeof PKV(179)[k]);
    PKV(180)[k] = 0;
    memset(PKV(178)[k], 0, sizeof PKV(178)[k]);
    chord_live_sync(k);
}
/* the track's latch state is gone (a panic ended every note; trk_all_off) */
static void latch_forget(uint32_t k)
{
    memset(PKV(179)[k], 0, sizeof PKV(179)[k]);
    PKV(180)[k] = 0;
    memset(PKV(178)[k], 0, sizeof PKV(178)[k]);
    memset(PKV(177)[k], 0, sizeof PKV(177)[k]);
    memset(PKV(181)[k], 0, sizeof PKV(181)[k]);
    chord_live_sync(k);
}
/* A rebuilt CHRD BUS chord must stay eligible only while some owner still holds it. */
static void chord_live_sync(uint32_t i)
{
    uint32_t k, m;
    for (k = 0; k < 27u; k++)
        if (PKV(170)[k] && PKV(173)[k] && PKV(146)[k] == i) {
            PKV(176)[i] = 1;
            return;
        }
    for (m = 0; m < 24u; m++)
        if (PKV(174)[m].id == i + 1u) {
            PKV(176)[i] = 1;
            return;
        }
    if (lat_any(PKV(178)[i]) || lat_any(PKV(179)[i]) || PKV(180)[i])
        PKV(176)[i] = 1;
    else
        PKV(176)[i] = 0;
}
/* Panic/CC120: no held panel key may re-arm the cached bus chord until a fresh press. The key's outgoing
 * NoteOff list stays intact; only its retrigger eligibility is gone. */
static void chord_panic(uint32_t i)
{
    uint32_t k;
    for (k = 0; k < 27u; k++)
        if (PKV(146)[k] == i)
            PKV(173)[k] = 0;
    PKV(176)[i] = 0;
}
/* Is there a real owner whose note list is exactly the cached chord? An unrelated remaining key (different
 * octave/voicing) must not resurrect chord_last. */
static int chord_owner_matches(uint32_t i, const uint8_t *old, uint32_t oldn)
{
    uint32_t k, m, j;
    for (k = 0; k < 27u; k++) {
        if (!PKV(170)[k] || !PKV(173)[k] || PKV(146)[k] != i || PKV(170)[k] != oldn)
            continue;
        for (j = 0; j < oldn && PKV(169)[k][j] == old[j]; j++)
            ;
        if (j == oldn)
            return 1;
    }
    for (m = 0; m < 24u; m++) {
        mchord_t *c = &PKV(174)[m];
        if (c->id != i + 1u || c->n != oldn)
            continue;
        for (j = 0; j < oldn && c->note[j] == old[j]; j++)
            ;
        if (j == oldn)
            return 1;
    }
    return oldn && PKV(180)[i];
}
/* The cached chord no longer belongs to any owner: select a surviving live owner and rebuild from its own input
 * key. This keeps a held low chord following HARMONY after the newest owner was released. */
static int chord_owner_fallback(uint32_t i, uint32_t *src, uint8_t *old, uint32_t *oldn)
{
    uint32_t k, m, j;
    for (k = 0; k < 27u; k++) {
        if (!PKV(170)[k] || !PKV(173)[k] || PKV(146)[k] != i)
            continue;
        *src = PKV(145)[k];
        *oldn = PKV(170)[k];
        for (j = 0; j < *oldn; j++)
            old[j] = PKV(169)[k][j];
        return 1;
    }
    for (m = 0; m < 24u; m++) {
        mchord_t *c = &PKV(174)[m];
        if (c->id != i + 1u)
            continue;
        *src = c->src;
        *oldn = c->n;
        for (j = 0; j < *oldn; j++)
            old[j] = c->note[j];
        return 1;
    }
    return 0;
}
/* HARMONY/LINK RETRIG for a LATCH-held chord that is not CHRD BUS: retrigger every latched note.
 * MONO/LEGATO/UNISON keep the full logical stack (a physically held newer note must stay newer) and every note
 * keeps the velocity it was played with. */
static void retrigger_latched(uint32_t i)
{
    track_t *t = &PKV(7)[i];
    uint32_t k = trk_index(t), n, j, nl = 0, nf = 0;
    uint8_t full[8], vel[8], order[8];
    if (trk_vmode(t) != V_POLY) {
        for (j = 0; j < t->nmono && nf < 8u; j++)
            full[nf++] = t->mono_stack[j];
        for (j = 0; j < nf; j++)
            if (lat_get(PKV(178)[k], full[j])) {
                order[nl] = full[j];
                vel[nl] = PKV(181)[k][order[nl]] ? PKV(181)[k][order[nl]] : 100u;
                nl++;
            }
        for (j = 0; j < nl; j++)
            trk_note_off(t, order[j]);
        for (j = 0; j < nl; j++)
            trk_note_on(t, order[j], vel[j]);
        for (j = 0; j < nf; j++) /* restore the complete stack order, held notes included */
            t->mono_stack[j] = full[j];
        t->nmono = (uint8_t)nf;
        {
            uint32_t want = mono_pick(t), v = t->v[0].vel ? t->v[0].vel : 100u;
            if (want && want != t->mono_note)
                mono_play(t, want, v, 0, 0);
        }
        return;
    }
    for (n = 0; n < 128u; n++) {
        if (!lat_get(PKV(178)[k], n))
            continue;
        uint8_t v = PKV(181)[k][n] ? PKV(181)[k][n] : 100u;
        trk_note_off(t, n);
        trk_note_on(t, n, v);
    }
}
/* A CHRD BUS retrigger replaces the notes in chord_last. The physical key and MIDI mchord still own the old
 * notes, so move those owners to the new list; a LATCH bit moves too. Without this a key-up would release only
 * the old chord and the new notes would hang. */
static void retrigger_owners(uint32_t i, const uint8_t *old, uint32_t oldn, const uint8_t *new_, uint32_t newn)
{
    uint32_t k, j, m;
    int was_latched = PKV(180)[i];
    uint8_t lv = 100u;
    for (j = 0; j < oldn; j++)
        if (lat_get(PKV(178)[i], old[j])) {
            lv = PKV(181)[i][old[j]] ? PKV(181)[i][old[j]] : 100u;
            break;
        }
    for (k = 0; k < 27u; k++) {
        if (!PKV(170)[k] || !PKV(173)[k] || PKV(146)[k] != i || PKV(170)[k] != oldn)
            continue;
        for (j = 0; j < oldn && PKV(169)[k][j] == old[j]; j++)
            ;
        if (j != oldn)
            continue;
        for (j = 0; j < newn; j++)
            PKV(169)[k][j] = new_[j];
        PKV(170)[k] = (uint8_t)newn;
    }
    for (m = 0; m < 24u; m++) {
        mchord_t *c = &PKV(174)[m];
        if (c->id != i + 1u || c->n != oldn)
            continue;
        for (j = 0; j < oldn && c->note[j] == old[j]; j++)
            ;
        if (j != oldn)
            continue;
        for (j = 0; j < newn; j++)
            c->note[j] = new_[j];
        c->n = (uint8_t)newn;
    }
    if (was_latched) {
        for (j = 0; j < oldn; j++) {
            if (!lat_get(PKV(179)[i], old[j])) {
                lat_put(PKV(178)[i], old[j], 0);
                PKV(181)[i][old[j]] = 0;
            }
            lat_put(PKV(177)[i], old[j], 0);
        }
        for (j = 0; j < newn; j++) {
            lat_put(PKV(178)[i], new_[j], 1);
            lat_put(PKV(177)[i], new_[j], 0);
            PKV(181)[i][new_[j]] = lv;
        }
    }
    for (j = 0; j < oldn; j++) /* round 7: a moved chord's stale 'this press ended it' marks go with it, or its release would swallow a later NoteOff */
        lat_put(PKV(177)[i], old[j], 0);
    for (j = 0; j < newn; j++)
        lat_put(PKV(177)[i], new_[j], 0);
}
static int midi_note_held(const track_t *t, uint32_t note);
static int midi_local_held(const track_t *t, uint32_t note);
static int chord_note_held(uint32_t i, uint32_t note)
{
    return midi_local_held(&PKV(7)[i], note) || midi_note_held(&PKV(7)[i], note) || lat_get(PKV(178)[i], note) || lat_get(PKV(179)[i], note);
}
static int midi_any_held(const track_t *t);
static void arp_drop(track_t *t, uint32_t note);
/* a note of track t sounds now because LATCH keeps it (without ARP: a voice or the mono stack plays it) */
static int lat_sounds(const track_t *t, uint32_t n)
{
    uint32_t i;
    if (trk_vmode(t) == V_POLY) {
        for (i = 0; i < 8; i++)
            if (t->v[i].active && t->v[i].gate && t->v[i].note == n)
                return 1;
        return 0;
    }
    for (i = 0; i < t->nmono; i++)
        if (t->mono_stack[i] == n)
            return 1;
    return 0;
}
/* A pitch a STACK press may end: latched itself, or kept by an older latched BUS chord while a held key now plays it (input_on takes it out
 * of lat_stay then), and sounding. */
static int lat_ends(const track_t *t, uint32_t n)
{
    uint32_t k = trk_index(t);
    return (lat_get(PKV(178)[k], n) || lat_get(PKV(179)[k], n)) && lat_sounds(t, n);
}
/* Would latch_press end these notes (STACK, no ARP, every one latched and sounding)? chord_build asks this before it replaces chord_last:
 * a press that only ends latched notes starts no new chord and must not take over the newest chord's identity. */
static int latch_would_toggle(const track_t *t, const uint8_t *nn, uint32_t n)
{
    uint32_t i;
    if (latch_mode(t) != LT_STACK || t->p[P_AMODE] || !n)
        return 0;
    for (i = 0; i < n; i++)
        if (!lat_ends(t, nn[i]))
            return 0;
    return 1;
}
/* a press (key, chord, MIDI note) of the n notes nn on track t, before they start: STACK and every one of them latched
 * (the ARP's list: held) ends them, and the press starts nothing (1; the release of each is eaten); NEW without ARP and no
 * key or note held ends the latched set. 0: the press goes on as always.
 * CHRD BUS: the pressed chord is the newest one (chord_last, latched) or an older one. Its tones end unless another latched chord
 * still holds them: an older chord's by the newest chord, the newest one's by the older ones (lat_bus_other, one bit per pitch: with
 * three or more overlapping chords an older chord's toggle cannot tell a shared tone of two older ones apart and ends it). The newest
 * chord stays the one that follows HARMONY when an older chord is pressed again. */
static int latch_press(track_t *t, const uint8_t *nn, uint32_t n)
{
    uint32_t k = trk_index(t), mode = latch_mode(t), i, j;
    if (mode == LT_OFF || !n)
        return 0;
    if (mode == LT_NEW) {
        if (!t->p[P_AMODE] && !midi_any_held(t))
            latch_free(t);
        return 0;
    }
    for (i = 0; i < n; i++) {
        if (t->p[P_AMODE]) {
            for (j = 0; j < t->nheld && t->held[j] != nn[i]; j++)
                ;
            if (j == t->nheld)
                return 0;
        } else if (!lat_ends(t, nn[i])) {
            return 0;
        }
    }
    {
        int bus = !t->p[P_AMODE] && t->p[P_CHRD] == CH_BUS, newest = 0;
        if (bus && PKV(180)[k] && n == PKV(175)[k].n) {
            newest = 1;
            for (i = 0; i < n; i++)
                newest &= nn[i] == PKV(175)[k].note[i];
        }
        for (i = 0; i < n; i++) {
            if (t->p[P_AMODE]) {
                arp_drop(t, nn[i]);
                lat_put(PKV(177)[k], nn[i], 1);
            } else {
                int keep = 0;
                if (bus) {
                    if (newest) {
                        keep = lat_get(PKV(179)[k], nn[i]); /* the newest chord ends: an older one may hold the tone */
                    } else {
                        lat_put(PKV(179)[k], nn[i], 0); /* an older chord ends: the newest one may hold the tone */
                        for (j = 0; PKV(180)[k] && j < PKV(175)[k].n; j++)
                            keep |= PKV(175)[k].note[j] == nn[i];
                    }
                    keep |= midi_local_held(t, nn[i]) || midi_note_held(t, nn[i]); /* a key / MIDI note / the sustain still plays it */
                }
                if (!keep) {
                    lat_put(PKV(178)[k], nn[i], 0);
                    trk_note_off(t, nn[i]);
                    lat_put(PKV(177)[k], nn[i], 1); /* its release does nothing; a kept tone's release goes on as ever */
                }
            }
        }
        if (!bus || newest)
            PKV(180)[k] = 0;
        if (bus)
            chord_live_sync(k);
    }
    return 1;
}
/* ------------------------------------------------------------- arp --- */
static void arp_add(track_t *t, uint32_t note)
{
    uint32_t i, k = PKV(147) - 1u;
    if (arp_replace(t) && t->arp_phys == 0u)
        t->nheld = 0; /* new chord replaces the latched one */
    t->arp_phys++; /* every key-down: arp_remove counts every key-up */
    for (i = 0; i < t->nheld; i++)
        if (t->held[i] == note)
            return; /* repeated note-on: not a new note */
    if (t->nheld < 16u) {
        /* #191: a key the track's scale keyboard maps (not the DRUM grid, not an engine's own map) is kept as that
         * key, so TRN, ROOT, SCALE and QNT reach the notes the arp holds (arp_list); the octave stays the one it was
         * pressed in. Anything else (MIDI IN) plays as it came, as before */
        uint8_t *hk = PKV(149)[trk_index(t)];
        hk[t->nheld] = PKV(147) && PKV(8).grid != 1u && kb_engine(t, k) < 0
                           ? (uint8_t)(PKV(147) | (uint32_t)(PKV(8).octave + 3) << 5) : 0u;
        PKV(150)[trk_index(t)][t->nheld] = (int8_t)(hk[t->nheld] ? (int32_t)note - PKV(145)[k] : 0);
        t->held[t->nheld++] = (uint8_t)note;
    }
    if (t->nheld == 1u) {
        t->arp_pos = 0xFFFFFFF; /* fire on this block */
        t->arp_idx = 0xFFFFFFFFu;
    }
}
/* the note leaves the held list */
static void arp_drop(track_t *t, uint32_t note)
{
    uint32_t i, k = 0;
    uint8_t *hk = PKV(149)[trk_index(t)];
    int8_t *dt = PKV(150)[trk_index(t)];
    for (i = 0; i < t->nheld; i++)
        if (t->held[i] != note) {
            hk[k] = hk[i];
            dt[k] = dt[i];
            t->held[k++] = t->held[i];
        }
    t->nheld = (uint8_t)k;
}
static void arp_remove(track_t *t, uint32_t note)
{
    if (t->arp_phys)
        t->arp_phys--;
    if (arp_hold(t))
        return;
    arp_drop(t, note);
}
static void rec_note(track_t *t, uint32_t note, uint32_t vel);
static void rec_release(track_t *t, uint32_t note);
static int rec_on(const track_t *t) {
    return (((PKV(8).rec & ~PKV(165)) >> trk_index(t)) & 1u) && PKV(8).playing && !PKV(142).running;
}
