static void host_tracks_init(void) /* as felucca_init: defaults, empty patterns */
{
    uint32_t i, k;
    for (i = 0; i < G_COUNT; i++)
        PKV(8).g[i] = GP[i].def;
    PKV(8).g[G_RTYPE] = 0; /* ROOM, the power-on reverb until 1.2: the renders (goldens) as
                                                   * before, ROOM bit for bit; HALL, the default since: reverb_test.c */
    for (k = 0; k < 4; k++) {
        for (i = 0; i < P_E0; i++)
            PKV(7)[k].p[i] = TP[i].def;
        for (i = 0; i < 64; i++)
            PKV(7)[k].step[i].time = ST_REST;
    }
    PKV(8).master_q12 = 4096;
}
static void host_preset_values(track_t *t, uint32_t e, uint32_t pi, const preset_t *p)
{
    static const uint8_t FX_DEF[4] = {0, 24, 28, 36};
    uint32_t i;
    t->eng_req = (uint8_t)e;
    t->preset = (uint8_t)pi;
    for (i = 0; i < 8u; i++)
        t->p[P_E0 + i] = p->e[i];
    t->p[P_ATK] = p->env[0];
    t->p[P_DEC] = p->env[1];
    t->p[P_SUS] = p->env[2];
    t->p[P_REL] = p->env[3];
    t->p[P_ED_FLT] = p->fenv;
    t->p[P_VOICE] = p->mono ? V_LEGATO : V_POLY;
    for (i = 0; i < 4u; i++)
        t->p[P_DIST + i] = (int16_t)(p->fx[i] ? p->fx[i] - 1 : FX_DEF[i]);
    t->p[P_SPRD] = e == 17u ? ens_width(pi) : 0; /* ui.c preset_sound_values: a factory load sets SPRD (the preset's width, else its default 0) */
    fm6_track_loaded(t); /* FM6: the preset's patch (ui.c apply_preset_to) */
}
static void host_preset_req(track_t *t, uint32_t e, uint32_t pi)
{
    uint32_t n = ENGINES[e]->npresets;
    if (e == 1u) { /* DIGITAL preset pi (retired): converted, as ui.c fm4_load_preset */
        uint8_t v[FP_SIZE + 1u];
        uint32_t tr = (uint32_t)(t - PKV(7)) % 4;
        fm4_preset_values(t->p, pi);
        t->preset = (uint8_t)fm4_convert(t->p, v);
        t->eng_req = 12u;
        fm6_set_patch(tr, v);
        PKV(33)[tr] = (uint8_t)t->p[P_E7];
        return;
    }
    if (!n) {
        t->eng_req = (uint8_t)e;
        t->preset = 0;
        for (uint32_t i = 0; i < 8u; i++)
            t->p[P_E0 + i] = ENGINES[e]->edit[i].def;
        return;
    }
    pi %= n;
    host_preset_values(t, e, pi, &ENGINES[e]->presets[pi]);
}
static void host_preset(track_t *t, uint32_t e, uint32_t pi)
{
    host_preset_req(t, e, pi);
    t->engine = t->eng_req; /* (DIGITAL without FELUCCA_FM4: FM6) */
    eng_mem_claim(t); /* (voice.c engine_block would at the next block) */
}
/* ------------------------------------------------------------------ Armada's glue (GPL-3.0-only, Gonzi Audio) --- */
enum { AG_NENGINES = 18u, AG_CTL = 32 };
static void ag_init(void)
{
    uint32_t k;
    
    host_tracks_init();
    for (k = 1; k < 4; k++)
        PKV(7)[k].p[P_MUTE] = 1; /* the plugin plays part 1 */
    PKV(8).sel = 0;
}
static void ag_kill(void)
{
    uint32_t i;
    track_t *t = &PKV(7)[0];
    trk_all_off(t);
    for (i = 0; i < 8; i++) {
        t->v[i].active = t->v[i].gate = 0;
        t->v[i].stage = 0;
        t->v[i].env = t->v[i].env_out = 0;
    }
}
static void ag_sound(uint32_t e, uint32_t s)
{
    ag_kill();
    host_preset(&PKV(7)[0], e, s);
}
static const char *ag_own_name(uint32_t e, uint32_t s, uint32_t *count)
{
    (void)e; (void)s;
    *count = 0;
    return 0;
}
static int32_t ag_getp(uint32_t id) { return PKV(7)[0].p[id]; }
static void ag_setp(uint32_t id, int32_t v)
{
    const param_desc_t *d = &TP[id];
    PKV(7)[0].p[id] = (int16_t)(v < d->min ? d->min : v > d->max ? d->max : v);
}
static void ag_sete(uint32_t k, int32_t v)
{
    const param_desc_t *d = &ENGINES[PKV(7)[0].engine]->edit[k];
    PKV(7)[0].p[P_E0 + k] = (int16_t)(v < d->min ? d->min : v > d->max ? d->max : v);
}
static void ag_setg(uint32_t id, int32_t v)
{
    const param_desc_t *d = &GP[id];
    PKV(8).g[id] = (int16_t)(v < d->min ? d->min : v > d->max ? d->max : v);
}
static void ag_note_on(uint32_t n, uint32_t vel) { trk_note_on(&PKV(7)[0], n, vel); }
static void ag_note_off(uint32_t n) { trk_note_off(&PKV(7)[0], n); }
static void ag_all_off(void) { trk_all_off(&PKV(7)[0]); }
static void ag_bend(int32_t q8) { PKV(58)[0] = (q8); }
static void ag_render(int32_t *o, uint32_t n) { mix_block(o, n); }
static void ag_format(uint32_t e, uint32_t k, int32_t v, char *val, const char **unit)
{
    const param_desc_t *d = &ENGINES[e]->edit[k];
    *unit = 0;
    param_format(d, v, val, unit);
}

